update student
SET sname = #{sname},grade = #{grade},school = #{school},
career = #{career},sclass = #{sclass},GPA = #{GPA},award = #{award},email = #{email},xb = #{xb},
csrq = #{csrq},hobby = #{hobby},phone = #{phone},phone2 = #{phone2}
